import {GUIDES,VERSION,searchGuides} from './einstein-guide.js';
const backend=()=>window.CAGE_BACKEND,$=id=>document.getElementById(id);
let owner='',turns=[],busy=false,epoch=0,closedSession=false;
const launcher=document.createElement('button');launcher.id='einstein-launcher';launcher.type='button';launcher.textContent='Ask Einstein';launcher.hidden=true;launcher.setAttribute('aria-controls','einstein-panel');launcher.setAttribute('aria-expanded','false');document.body.append(launcher);
const panel=document.createElement('aside');panel.id='einstein-panel';panel.hidden=true;panel.setAttribute('aria-label','Einstein assistant');panel.innerHTML=`<header><div><span class="einstein-mark" aria-hidden="true">E</span><div><h2>Einstein</h2><p>Your guide to CAGE</p></div></div><button type="button" id="einstein-close" aria-label="Close Einstein">×</button></header><div class="einstein-context" id="einstein-context"></div><div id="einstein-thread" role="log" aria-live="polite" aria-relevant="additions"></div><div id="einstein-guides"></div><p id="einstein-status" role="status"></p><form id="einstein-form"><label for="einstein-question">How can I help?</label><textarea id="einstein-question" rows="3" maxlength="4000" required placeholder="How do I send a quotation?"></textarea><label class="einstein-check"><input type="checkbox" id="einstein-context-opt"> Include work details from this page (projects, tasks, requests or CRM only)</label><small>Your question and recent conversation are sent to OpenAI when you choose Ask Einstein. Built-in guides work without AI.</small><div class="einstein-actions"><button type="button" id="einstein-clear">New conversation</button><button type="submit" id="einstein-send">Ask Einstein</button></div></form>`;document.body.append(panel);
function profile(){return backend()?.currentProfile?.();}
function current(){return typeof activeView==='string'?activeView:'mywork';}
function permitted(view){return !!profile()&&profile().active!==false&&profile().role!=='shared'&&(view==='mywork'||backend().moduleLevel(view)!=='none');}
function storageKey(){return 'cage-einstein:'+owner;}
function save(){try{sessionStorage.setItem(storageKey(),JSON.stringify(turns.slice(-16)));}catch{}}
function add(role,text){turns.push({role,content:String(text).slice(0,8000)});turns=turns.slice(-16);save();render();}
function render(){const thread=$('einstein-thread');thread.replaceChildren();for(const t of turns){const card=document.createElement('article');card.className='einstein-message '+t.role;const name=document.createElement('strong');name.textContent=t.role==='user'?'You':'Einstein';const content=document.createElement('p');content.textContent=t.content;card.append(name,content);thread.append(card);}thread.scrollTop=thread.scrollHeight;}
function guideButtons(list){const box=$('einstein-guides');box.replaceChildren();for(const g of list.filter(g=>permitted(g.view))){const b=document.createElement('button');b.type='button';b.textContent=g.title;b.onclick=()=>showGuide(g);box.append(b);}}
function showGuide(g){if(!permitted(g.view))return;add('assistant',g.title+'\n\n'+g.steps.map((s,i)=>`${i+1}. ${s}`).join('\n\n')+'\n\nBuilt-in Hub guide · '+VERSION);const b=document.createElement('button');b.type='button';b.className='einstein-open';b.textContent='Open '+(document.querySelector(`.nav-item[data-view="${g.view}"]>span:nth-child(2)`)?.innerText?.replace(/\s+/g,' ').trim()||g.view);b.onclick=()=>{if(!permitted(g.view)){ $('einstein-status').textContent='Your access has changed. Ask an administrator for help.';return;}close();setView(g.view);};$('einstein-thread').lastElementChild.append(b);b.scrollIntoView({block:'nearest'});}
function reset(){epoch++;turns=[];busy=false;$('einstein-send').disabled=false;$('einstein-question').value='';$('einstein-context-opt').checked=false;$('einstein-status').textContent='';save();render();guideButtons(GUIDES.filter(g=>g.view===current()).concat(GUIDES.filter(g=>g.view!==current())).filter(g=>permitted(g.view)).slice(0,4));}
function sync(){const p=closedSession?null:profile(),id=p?.active!==false&&p?.role!=='shared'?p?.id||'':'';launcher.hidden=!id;if(id!==owner){close();epoch++;turns=[];if(owner)try{sessionStorage.removeItem(storageKey());}catch{}owner=id;if(owner)try{const saved=JSON.parse(sessionStorage.getItem(storageKey())||'[]');if(Array.isArray(saved))turns=saved.filter(t=>['user','assistant'].includes(t.role)&&typeof t.content==='string').slice(-16);}catch{}render();busy=false;$('einstein-send').disabled=false;$('einstein-question').value='';$('einstein-context-opt').checked=false;}if(!panel.hidden){$('einstein-context').textContent='Helping with: '+(document.querySelector('.nav-item.active>span:nth-child(2)')?.innerText?.replace(/\s+/g,' ').trim()||current());}}
function close(){panel.hidden=true;launcher.setAttribute('aria-expanded','false');}
launcher.onclick=()=>{sync();panel.hidden=!panel.hidden;launcher.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){sync();guideButtons(GUIDES.filter(g=>g.view===current()).concat(GUIDES.filter(g=>g.view!==current())).filter(g=>permitted(g.view)).slice(0,4));if(!turns.length)add('assistant','Hello, I’m Einstein. Ask me how to use the Hub, or select a built-in guide below. I can explain and draft; I cannot send emails or change your records.');$('einstein-question').focus();}};
$('einstein-close').onclick=()=>{close();launcher.focus();};$('einstein-clear').onclick=reset;
$('einstein-question').addEventListener('input',()=>guideButtons(searchGuides($('einstein-question').value,current())));
$('einstein-form').onsubmit=async e=>{e.preventDefault();sync();if(busy||!owner)return;const question=$('einstein-question').value.trim();if(!question)return;const history=turns.slice(-8).map(t=>({...t,content:t.content.slice(0,4000)}));const token=epoch,who=owner;busy=true;$('einstein-send').disabled=true;add('user',question);$('einstein-status').textContent='Einstein is thinking…';try{const result=await backend().askEinstein({question,history,page:current(),includeContext:$('einstein-context-opt').checked});if(token!==epoch||who!==profile()?.id)return;add('assistant',result.answer);$('einstein-question').value='';$('einstein-status').textContent='AI answer — check important details. '+(result.remaining!==undefined?result.remaining+' questions remaining today.':'');guideButtons(GUIDES.filter(g=>(result.guides||[]).includes(g.id)));}catch(err){if(token!==epoch||who!==profile()?.id)return;$('einstein-status').textContent=err.message+' Your question is kept for retry.';guideButtons(searchGuides(question,current()));}finally{if(token===epoch){busy=false;$('einstein-send').disabled=false;}}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){close();launcher.focus();}});
window.addEventListener('cage:session-ready',()=>{closedSession=false;sync();});window.addEventListener('cage:access-closed',()=>{closedSession=true;reset();close();launcher.hidden=true;owner='';});$('sign-out-button')?.addEventListener('click',()=>{closedSession=true;reset();close();launcher.hidden=true;owner='';},true);
setInterval(sync,1000);sync();
